from flask import request, send_file, Flask
import os

app = Flask(__name__)

@app.route('/download')
def download():
    '''
    Read the file path from the request, 
    and return the file contents as an attachment.
    '''
    file_path = request.args.get('file_path', '')

    # Normalize and validate the file path to prevent directory traversal attacks
    safe_file_path = os.path.abspath(os.path.join('/safe/directory/', file_path))

    if not safe_file_path.startswith('/safe/directory/'):
        return "Invalid file path", 403

    try:
        with open(safe_file_path, 'rb') as f:
            return send_file(f.read(), attachment_filename=os.path.basename(file_path))
    except FileNotFoundError:
        return "File not found", 404
